xml.Script:
        clYellow       := 'FFFF00';
        clBlue         := '0000A0';
        clOrange       := 'FF6000';
        clRed          := 'FF0000';
        clGreen        := '008000';
        clWhite        := 'FFFFFF';
        clGolden       := 'AABB20';
        clLightViolett := 'FF0080';
        clLightBlue    := '2828FF';
        clViolett      := '800080';
        clBrown        := '800000';
        clLightGreen   := '00FF00';
        clCyan         := '00DCB4';
        clPink         := 'FF69B4';

        R := 0.4;
        H := R * cos(Pi/7) / sqrt(cos(3 * Pi/7));

        for i := 0 to 6 do begin
            x[i] := R * cos(2 * Pi / 7 * i);
            y[i] := R * sin(2 * Pi / 7 * i);
        end;

        az := R * cos(Pi/7) / H;
        for i := 0 to 6 do begin
            ax[i] := cos(2 * Pi / 7 * (i + 0.5));
            ay[i] := sin(2 * Pi / 7 * (i + 0.5));
        end;

        // Calcs angle from 2 to 3 while rotating over 1
        function Angle(x1, y1, z1, x2, y2, z2, x3, y3, z3);
        begin
          vx := y1 * z2 - y2 * z1;
          vy := z1 * x2 - z2 * x1;
          vz := x1 * y2 - x2 * y1;
          wx := y1 * z3 - y3 * z1;
          wy := z1 * x3 - z3 * x1;
          wz := x1 * y3 - x3 * y1;
          Result := ArcCos((vx*wx + vy*wy + vz*wz) / (vx^2 + vy^2 + vz^2));
        end;

        // Calc all Jumble Angles
        A1 := Angle(ax[3],ay[3],az, ax[2],ay[2],az, ax[4],ay[4],az);
        A2 := Angle(ax[3],ay[3],az, ax[1],ay[1],az, ax[5],ay[5],az);
        A3 := Angle(ax[3],ay[3],az, ax[0],ay[0],az, ax[6],ay[6],az);
